/**
 * 2D geometric shapes and colours: the cards of the "2D Geometric Colored
 * Shapes" set (public/cards/shapes, generated by scripts/build-shapes.ts) and
 * the players' avatars (drawn inline with the same code).
 *
 * Every shape is drawn in a 100 × 100 box, with a thin dark outline so that
 * white shapes stay visible on white cards.
 *
 * This module has no imports, so that Node can run the generator script
 * directly from TypeScript.
 */

export const SHAPES = [
  'circle',
  'equilateralTriangle',
  'isoscelesTriangle',
  'scaleneTriangle',
  'rightTriangle',
  'square',
  'rectangle',
  'rhombus',
  'parallelogram',
  'trapezium',
  'pentagon',
  'hexagon',
  'heptagon',
  'octagon',
  'nonagon',
  'decagon',
  'star',
  'crescent',
  'cross',
  'heart',
  'ellipse',
  'ring',
  'semicircle',
  'dodecagon',
  'pentadecagon',
  'icosagon',
  'circleSector',
  'lemniscate',
  'trefoil',
  'quatrefoil',
] as const;
export type ShapeId = (typeof SHAPES)[number];

/** The rainbow colours, then black, grey, white, brown and pink. */
export const COLORS = {
  red: '#E4002B',
  orange: '#FF8200',
  yellow: '#FFCD00',
  green: '#00843D',
  blue: '#1F6FEB',
  indigo: '#3F2FA8',
  violet: '#9B3FD9',
  black: '#121212',
  grey: '#8A8A8A',
  white: '#FFFFFF',
  brown: '#8B5A2B',
  pink: '#F472B6',
} as const;
export type ColorId = keyof typeof COLORS;
export const COLOR_IDS = Object.keys(COLORS) as ColorId[];

export function isShape(v: unknown): v is ShapeId {
  return SHAPES.includes(v as ShapeId);
}

/** Outline drawn around every shape. */
const OUTLINE = '#121212';
const OUTLINE_OPACITY = 0.55;
const OUTLINE_WIDTH = 3;

const f = (n: number) => String(Math.round(n * 100) / 100);
const pts = (points: [number, number][]) => points.map(([x, y]) => `${f(x)},${f(y)}`).join(' ');
const polygon = (points: [number, number][]) => `<polygon points="${pts(points)}"/>`;

/** A regular polygon with `n` corners, one at the top, visually centred. */
function regular(n: number, r = 44): string {
  // Odd polygons have a flat bottom side: move them down to balance the space.
  const cy = 50 + (n % 2 ? (r - r * Math.cos(Math.PI / n)) / 2 : 0);
  const points: [number, number][] = [];
  for (let i = 0; i < n; i++) {
    const a = -Math.PI / 2 + (2 * Math.PI * i) / n;
    points.push([50 + r * Math.cos(a), cy + r * Math.sin(a)]);
  }
  return polygon(points);
}

function star(cx: number, cy: number, r: number, inner = 0.382): string {
  const points: [number, number][] = [];
  for (let i = 0; i < 10; i++) {
    const radius = i % 2 === 0 ? r : r * inner;
    const a = -Math.PI / 2 + (i * Math.PI) / 5;
    points.push([cx + radius * Math.cos(a), cy + radius * Math.sin(a)]);
  }
  return polygon(points);
}

/** A crescent: the outer circle minus a second circle shifted to the right. */
function crescent(): string {
  const [cx, cy, R] = [46, 50, 40];
  const [dx, r] = [17, 33];
  // Intersection of the two circles (x is the same for both points).
  const x = (dx * dx + R * R - r * r) / (2 * dx);
  const y = Math.sqrt(R * R - x * x);
  const top = [cx + x, cy - y];
  const bottom = [cx + x, cy + y];
  return `<path d="M${f(top[0])} ${f(top[1])} A${R} ${R} 0 1 0 ${f(bottom[0])} ${f(bottom[1])} A${r} ${r} 0 1 1 ${f(top[0])} ${f(top[1])}Z"/>`;
}

/** Bernoulli's lemniscate (∞), as a thick line. */
function lemniscatePath(): string {
  const a = 42;
  const parts: string[] = [];
  for (let i = 0; i <= 96; i++) {
    const t = (i / 96) * 2 * Math.PI;
    const d = 1 + Math.sin(t) ** 2;
    parts.push(`${i ? 'L' : 'M'}${f(50 + (a * Math.cos(t)) / d)} ${f(50 + (a * Math.sin(t) * Math.cos(t)) / d)}`);
  }
  return parts.join('') + 'Z';
}

/** Circles placed around the centre (trefoil, quatrefoil). */
function foil(n: number, r: number, dist: number, cy = 50): string {
  let out = '';
  for (let i = 0; i < n; i++) {
    const a = -Math.PI / 2 + (2 * Math.PI * i) / n + (n === 4 ? Math.PI / 4 : 0);
    out += `<circle cx="${f(50 + dist * Math.cos(a))}" cy="${f(cy + dist * Math.sin(a))}" r="${r}"/>`;
  }
  // The middle, so that no gap is left between the leaves.
  return out + `<circle cx="50" cy="${cy}" r="${dist}"/>`;
}

/** The filled parts of a shape (drawn twice: as the outline, then in colour). */
function body(shape: ShapeId): string {
  switch (shape) {
    case 'circle':
      return '<circle cx="50" cy="50" r="42"/>';
    case 'equilateralTriangle': {
      const s = 88;
      const h = (s * Math.sqrt(3)) / 2;
      const top = 50 - h / 2;
      return polygon([[50, top], [50 + s / 2, top + h], [50 - s / 2, top + h]]);
    }
    case 'isoscelesTriangle':
      return polygon([[50, 5], [76, 95], [24, 95]]);
    case 'scaleneTriangle':
      return polygon([[30, 14], [94, 84], [6, 84]]);
    case 'rightTriangle':
      return polygon([[12, 10], [12, 90], [90, 90]]);
    case 'square':
      return '<rect x="12" y="12" width="76" height="76"/>';
    case 'rectangle':
      return '<rect x="4" y="25" width="92" height="50"/>';
    case 'rhombus':
      return polygon([[50, 4], [84, 50], [50, 96], [16, 50]]);
    case 'parallelogram':
      return polygon([[28, 24], [96, 24], [72, 76], [4, 76]]);
    case 'trapezium':
      return polygon([[28, 24], [72, 24], [96, 76], [4, 76]]);
    case 'pentagon':
      return regular(5);
    case 'hexagon':
      return regular(6);
    case 'heptagon':
      return regular(7);
    case 'octagon':
      return regular(8);
    case 'nonagon':
      return regular(9);
    case 'decagon':
      return regular(10);
    case 'dodecagon':
      return regular(12);
    case 'pentadecagon':
      return regular(15);
    case 'icosagon':
      return regular(20);
    case 'star':
      return star(50, 53, 47);
    case 'crescent':
      return crescent();
    case 'cross':
      return polygon([
        [37, 6], [63, 6], [63, 37], [94, 37], [94, 63], [63, 63],
        [63, 94], [37, 94], [37, 63], [6, 63], [6, 37], [37, 37],
      ]);
    case 'heart':
      return '<path d="M50 90C22 70 5 52 5 33C5 18 16 8 29 8C39 8 46 14 50 22C54 14 61 8 71 8C84 8 95 18 95 33C95 52 78 70 50 90Z"/>';
    case 'ellipse':
      return '<ellipse cx="50" cy="50" rx="46" ry="28"/>';
    case 'ring':
      return '<path fill-rule="evenodd" d="M50 8a42 42 0 1 0 0.01 0ZM50 30a20 20 0 1 1 -0.01 0Z"/>';
    case 'semicircle':
      return '<path d="M4 70A46 46 0 0 1 96 70Z"/>';
    case 'circleSector':
      return '<path d="M50 88L5.75 43.75A62.6 62.6 0 0 1 94.25 43.75Z"/>';
    case 'lemniscate':
      return `<path d="${lemniscatePath()}" fill="none" stroke-width="13" stroke-linejoin="round"/>`;
    case 'trefoil':
      return foil(3, 25, 22, 54);
    case 'quatrefoil':
      return foil(4, 22, 21);
  }
}

/** Extra outline-only details: the right angle mark of the right triangle. */
function details(shape: ShapeId): string {
  if (shape !== 'rightTriangle') return '';
  return `<path d="M12 78H24V90" fill="none" stroke="${OUTLINE}" stroke-opacity="${OUTLINE_OPACITY}" stroke-width="2.5"/>`;
}

/**
 * The inner SVG markup of a shape in `color` (any #RRGGBB colour): a dark
 * outline under the coloured shape. Line shapes (the lemniscate) are drawn
 * with strokes, the others are filled.
 */
export function shapeMarkup(shape: ShapeId, color: string): string {
  const inner = body(shape);
  if (shape === 'lemniscate') {
    const wide = inner.replace('stroke-width="13"', `stroke-width="${13 + 2 * OUTLINE_WIDTH}"`);
    return (
      `<g stroke="${OUTLINE}" opacity="${OUTLINE_OPACITY}">${wide}</g>` +
      `<g stroke="${color}">${inner}</g>`
    );
  }
  return (
    `<g fill="${OUTLINE}" stroke="${OUTLINE}" opacity="${OUTLINE_OPACITY}" stroke-width="${2 * OUTLINE_WIDTH}" stroke-linejoin="round">${inner}</g>` +
    `<g fill="${color}">${inner}</g>` +
    details(shape)
  );
}

/** A complete SVG document of a shape, as written to public/cards/shapes. */
export function shapeSvg(shape: ShapeId, color: string): string {
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="-2 -2 104 104">${shapeMarkup(shape, color)}</svg>\n`;
}

/** Id of a card of the shapes set, e.g. "red-circle"; also its file name without extension. */
export function shapeCardId(color: ColorId, shape: ShapeId): string {
  return `${color}-${shape.replace(/[A-Z]/g, (c) => '-' + c.toLowerCase())}`;
}
